class ConsultaUnior extends PDOStatement {
 protected function __construct() {}
 private function adaptar(mixed $row): mixed {
  if(!is_array($row))return $row;$reverse=array_flip(diccionarioBase());$out=[];
  foreach($row as $key=>$value)$out[is_string($key)?($reverse[$key]??$key):$key]=$value;return $out;
 }
 public function fetch(int $mode=PDO::FETCH_DEFAULT,int $orientation=PDO::FETCH_ORI_NEXT,int $offset=0): mixed { return $this->adaptar(parent::fetch($mode,$orientation,$offset)); }
 public function fetchAll(int $mode=PDO::FETCH_DEFAULT,mixed ...$args): array { return array_map(fn($row)=>$this->adaptar($row),parent::fetchAll($mode,...$args)); }
}
